import logging,json,os,datetime
logger=logging.getLogger()
def handler(event,context):
 if event.get("override"): logger.setLevel(logging.DEBUG)
 print("plain-"+event["marker"])
 for level in ["DEBUG","INFO","WARNING","ERROR","CRITICAL"]: logger.log(getattr(logging,level),"library-"+event["marker"]+"-"+level)
 for level in ["debug","INFO","WARN","ERROR","FATAL","nonsense"]: print(json.dumps({"timestamp":datetime.datetime.now(datetime.timezone.utc).isoformat(),"level":level,"message":"raw-"+event["marker"]+"-"+level}))
 print(json.dumps({"level":"ERROR","message":"missing-time-"+event["marker"]}))
 return {k:os.environ.get(k) for k in ["AWS_LAMBDA_LOG_FORMAT","AWS_LAMBDA_LOG_LEVEL","_LAMBDA_TELEMETRY_LOG_FD"]}
